<script setup lang="ts">
import type {BudgetSummary} from '../explorationApi'
import {yuan} from '../money'
defineProps<{budget:BudgetSummary;historical?:boolean}>()
const categories:Record<string,string>={tickets:'门票与演出',dining:'餐饮',transport:'交通',lodging:'住宿',other:'其他',spent:'已支付'}
const units:Record<string,string>={per_person:'人',per_party:'整组',per_vehicle:'车',per_person_day:'人／天',per_room_night:'间夜',per_room_stay:'间',party_stay:'整段住宿',party_report:'笔',stay:'笔'}
const basis:Record<string,string>={quoted:'资料金额',estimate:'估计',reported:'手填',unknown:'待核对'}
</script>
<template><section class="budget-breakdown" aria-label="全程费用明细"><h3>{{historical?'已确认的费用快照':'全程费用明细'}}</h3><p><strong>已计入 {{yuan(budget.known_total_fen)}}</strong><span v-if="budget.per_person_fen!=null"> · 人均 {{yuan(budget.per_person_fen)}}</span></p><p v-if="budget.limit_fen!=null">全程预算 {{yuan(budget.limit_fen)}}<template v-if="budget.remaining_fen!=null"> · {{budget.remaining_fen<0?'超出':'结余'}} {{yuan(Math.abs(budget.remaining_fen))}}</template></p><p role="status">{{budget.status==='over'?'当前核算超出预算':budget.unknown_items.length?'仍有未计入费用，暂不能判断预算够用':budget.status==='within_budget'?'当前核算在预算内':'未设置预算上限'}}{{budget.estimated?'；包含估计或手填金额':''}}。</p><p v-for="(amount,category) in budget.by_category" :key="category">{{categories[category]||category}}：{{yuan(amount)}}</p><details><summary>查看按日与逐项费用</summary><p v-for="(amount,day) in budget.by_day" :key="day">{{day}}：{{yuan(amount)}}</p><ul><li v-for="item in budget.items" :key="item.cost_id">{{item.day?item.day+' · ':''}}{{item.label}}：{{item.amount_fen==null?'待补充':yuan(item.amount_fen)}}（{{basis[item.basis]}}<template v-if="item.quantity!=null"> · 共 {{item.quantity}} {{units[item.unit]||'份'}}</template>）<small>{{item.source}}<span v-for="note in item.notes" :key="note"> · {{item.category==='spent'?'已覆盖：':''}}{{note}}</span></small></li></ul><p>整段住宿计入入住日，按日金额为支出归属，不表示各晚均价。</p></details><ul v-if="budget.unknown_items.length" aria-label="未计入费用"><li v-for="item in budget.unknown_items" :key="item">{{item}}</li></ul></section></template>
<style scoped>.budget-breakdown{margin:16px 0;padding:14px;background:#f4efe4;border:1px solid #ded4c2;border-radius:10px;font-size:13px;line-height:1.7}.budget-breakdown h3{margin:0;font:19px 'Songti SC',serif}.budget-breakdown summary{min-height:36px;cursor:pointer}.budget-breakdown small{display:block;color:#7a715d;overflow-wrap:anywhere}.budget-breakdown ul{padding-left:18px}.budget-breakdown li{margin:8px 0}</style>
